import {
    assignPrototypeAPIs,
    assignTableAPIs,
    columnFacetingFeature,
    type ColumnFilter,
    columnFilteringFeature,
    columnOrderingFeature,
    columnPinningFeature,
    columnSizingFeature,
    columnVisibilityFeature,
    createFacetedMinMaxValues,
    createFacetedUniqueValues,
    createPaginatedRowModel,
    createSortedRowModel,
    functionalUpdate,
    makeStateUpdater,
    metaHelper,
    type OnChangeFn,
    type RowData,
    rowPaginationFeature,
    rowSelectionFeature,
    rowSortingFeature,
    setStateSlice,
    sortFn_alphanumeric,
    sortFn_datetime,
    sortFn_text,
    type Table,
    type TableFeature,
    type TableFeatures,
    tableFeatures,
    type Updater,
    globalFilteringFeature,
} from '@tanstack/react-table';

import type {
    ColumnFilterItem,
    DataTableColumnMeta,
    DataTableTableMeta,
    JoinOperator,
} from '@/lib/data-table-types';

import {
    createDataTableFacetedRowModel,
    createDataTableFilteredRowModel,
    dataTableFilterFn,
} from '@/lib/data-table-filters';
import {
    getFilterVariant,
    getIsPlainFilter,
    getPlainFilterValue,
    normalizeColumnFilter,
} from '@/lib/data-table-utils';

interface TableState_DataTableFiltering {
    joinOperator: JoinOperator;
}

interface TableOptions_DataTableFiltering {
    onJoinOperatorChange?: OnChangeFn<JoinOperator>;
}

interface Table_DataTableFiltering {
    getColumnFilterItems: () => ColumnFilterItem[];
    addColumnFilter: (filter: ColumnFilterItem) => void;
    updateColumnFilter: (
        filterId: string,
        updates: Partial<Omit<ColumnFilterItem, 'filterId'>>,
    ) => void;
    removeColumnFilter: (filterId: string) => void;
    getJoinOperator: () => JoinOperator;
    setJoinOperator: (updater: Updater<JoinOperator>) => void;
    resetJoinOperator: (defaultState?: boolean) => void;
}

declare module '@tanstack/react-table' {
    interface Plugins {
        dataTableFilteringFeature: TableFeature;
    }

    interface TableState_FeatureMap {
        dataTableFilteringFeature: TableState_DataTableFiltering;
    }

    interface TableOptions_FeatureMap<
        in out TFeatures extends TableFeatures,
        in out TData extends RowData,
    > {
        dataTableFilteringFeature: TableOptions_DataTableFiltering;
    }

    interface Table_FeatureMap<
        in out TFeatures extends TableFeatures,
        in out TData extends RowData,
    > {
        dataTableFilteringFeature: Table_DataTableFiltering;
    }
}

type DataTableInstance = Table<DataTableFeatures, RowData>;

const dataTableFilteringFeature: TableFeature = {
    getInitialState: (initialState) => ({
        joinOperator: 'and',
        ...initialState,
    }),
    getDefaultColumnDef: () => ({
        enableColumnFilter: false,
        filterFn: dataTableFilterFn,
    }),
    getDefaultTableOptions: (table) => {
        const options: TableOptions_DataTableFiltering = {
            onJoinOperatorChange: makeStateUpdater('joinOperator', table),
        };
        return options;
    },
    assignColumnPrototype: (prototype, table) => {
        const instance = asDataTable(table);

        assignPrototypeAPIs('dataTableFilteringFeature', prototype, table, {
            column_getFilterValue: {
                fn: (column: { id: string }) =>
                    getPlainFilter(
                        instance,
                        column.id,
                        instance.atoms.columnFilters.get(),
                    ).value,
                memoDeps: () => [instance.atoms.columnFilters.get()],
            },
            column_setFilterValue: {
                fn: (column: { id: string }, updater: Updater<unknown>) =>
                    setPlainFilter(instance, column.id, updater),
            },
        });
    },
    constructTableAPIs: (table) => {
        const instance = asDataTable(table);
        const resolve = (filter: ColumnFilter) =>
            normalizeColumnFilter(
                filter,
                getFilterVariant(instance.getColumn(filter.id)?.columnDef.meta),
            );

        const setJoinOperator = (updater: Updater<JoinOperator>) =>
            instance.options.onJoinOperatorChange?.((old) =>
                functionalUpdate(updater, old),
            );

        assignTableAPIs('dataTableFilteringFeature', table, {
            table_setColumnFilters: {
                fn: (updater: Updater<ColumnFilter[]>) =>
                    setStateSlice(
                        table,
                        'columnFilters',
                        (old: ColumnFilter[]) =>
                            functionalUpdate(updater, old).filter(
                                (filter) =>
                                    !getShouldRemoveFilter(filter, instance),
                            ),
                    ),
            },
            table_getColumnFilterItems: {
                fn: () => instance.atoms.columnFilters.get().map(resolve),
                memoDeps: () => [instance.atoms.columnFilters.get()],
            },
            table_addColumnFilter: {
                fn: (filter: ColumnFilterItem) =>
                    instance.setColumnFilters((old) => [...old, filter]),
            },
            table_updateColumnFilter: {
                fn: (
                    filterId: string,
                    updates: Partial<Omit<ColumnFilterItem, 'filterId'>>,
                ) =>
                    instance.setColumnFilters((old) =>
                        old.map((filter) => {
                            const item = resolve(filter);
                            return item.filterId === filterId
                                ? { ...item, ...updates }
                                : filter;
                        }),
                    ),
            },
            table_removeColumnFilter: {
                fn: (filterId: string) =>
                    instance.setColumnFilters((old) =>
                        old.filter(
                            (filter) => resolve(filter).filterId !== filterId,
                        ),
                    ),
            },
            table_getJoinOperator: {
                fn: () => instance.atoms.joinOperator.get(),
            },
            table_setJoinOperator: { fn: setJoinOperator },
            table_resetJoinOperator: {
                fn: (defaultState?: boolean) =>
                    setJoinOperator(
                        defaultState
                            ? 'and'
                            : (instance.initialState.joinOperator ?? 'and'),
                    ),
            },
        });
    },
};

/**
 * Feature hooks get a `Table` generic over any features. This feature is only
 * registered in `dataTableFeatures`, so its hooks can use that table's types.
 */
function asDataTable(table: object) {
    return table as DataTableInstance;
}

function getPlainFilter(
    instance: DataTableInstance,
    columnId: string,
    filters: ColumnFilter[],
) {
    const variant = getFilterVariant(
        instance.getColumn(columnId)?.columnDef.meta,
    );
    const index = filters.findIndex(
        (filter) =>
            filter.id === columnId &&
            getIsPlainFilter(normalizeColumnFilter(filter, variant)),
    );
    const filter = filters[index];
    const value = filter
        ? getPlainFilterValue(normalizeColumnFilter(filter, variant))
        : undefined;

    return { index, filter, value };
}

function setPlainFilter(
    instance: DataTableInstance,
    columnId: string,
    updater: Updater<unknown>,
) {
    instance.setColumnFilters((old) => {
        const {
            index,
            filter: previous,
            value: previousValue,
        } = getPlainFilter(instance, columnId, old);
        const value = functionalUpdate(updater, previousValue);
        const next: ColumnFilter = previous?.filterId
            ? { id: columnId, value, filterId: previous.filterId }
            : { id: columnId, value };

        if (index === -1) return [...old, next];
        return old.map((filter, filterIndex) =>
            filterIndex === index ? next : filter,
        );
    });
}

/**
 * TanStack's `autoRemove` rules for plain filters. Filters with an
 * `operator` are only removed by an `undefined` value, so empty drafts in the
 * filter list survive a column `filterFn` whose `autoRemove` would drop them.
 */
function getShouldRemoveFilter(
    filter: ColumnFilter,
    instance: DataTableInstance,
) {
    if (filter.value === undefined) return true;
    if (filter.operator) return false;

    const column = instance.getColumn(filter.id);
    if (!column) return false;

    const filterFn = column.getFilterFn();
    if (filterFn?.autoRemove) {
        return filterFn.autoRemove(filter.value, column);
    }
    return typeof filter.value === 'string' && !filter.value;
}

export const dataTableFeatures = tableFeatures({
    columnFilteringFeature,
    globalFilteringFeature,
    columnFacetingFeature,
    columnOrderingFeature,
    columnPinningFeature,
    columnSizingFeature,
    columnVisibilityFeature,
    rowPaginationFeature,
    rowSelectionFeature,
    rowSortingFeature,
    dataTableFilteringFeature,
    filteredRowModel: createDataTableFilteredRowModel(),
    facetedRowModel: createDataTableFacetedRowModel(),
    facetedUniqueValues: createFacetedUniqueValues(),
    facetedMinMaxValues: createFacetedMinMaxValues(),
    paginatedRowModel: createPaginatedRowModel(),
    sortedRowModel: createSortedRowModel(),
    sortFns: {
        alphanumeric: sortFn_alphanumeric,
        datetime: sortFn_datetime,
        text: sortFn_text,
    },
    columnMeta: metaHelper<DataTableColumnMeta>(),
    tableMeta: metaHelper<DataTableTableMeta>(),
});

export type DataTableFeatures = typeof dataTableFeatures;

// Copyright (c) 2024 Sadman Sakib. SPDX-License-Identifier: MIT

import {
    type ColumnFilter,
    constructFilterFn,
    constructRow,
    type FilterFn,
    makeObjectMap,
    type Row,
    type RowData,
    type RowModel,
    skipFirstRun,
    type Table,
    type TableFeatures,
    tableMemo,
} from '@tanstack/react-table';

import type {
    ColumnFilterItem,
    DataTableColumnMeta,
    JoinOperator,
} from '@/lib/data-table-types';

import {
    createPlainFilter,
    getFilterVariant,
    getIsActiveFilter,
    normalizeColumnFilter,
    parseFilterDate,
    stringifyFilterValue,
} from '@/lib/data-table-utils';

const DAY_MS = 24 * 60 * 60 * 1000;
const GLOBAL_FILTER_ID = '__global__';

const filterResultsByRow = new WeakMap<object, Record<string, boolean>>();

export function matchesFilter(
    cellValue: unknown,
    filter: Pick<ColumnFilterItem, 'operator' | 'variant' | 'value'>,
): boolean {
    const { operator, variant, value } = filter;
    const isDate = variant === 'date' || variant === 'date-range';
    const isNumeric = variant === 'number' || variant === 'range';

    switch (operator) {
        case 'iLike':
            return typeof value === 'string'
                ? getLowercaseText(cellValue).includes(value.toLowerCase())
                : true;

        case 'notILike':
            return typeof value === 'string'
                ? !getLowercaseText(cellValue).includes(value.toLowerCase())
                : true;

        case 'eq':
            if (variant === 'boolean')
                return getBooleanString(cellValue) === value;
            if (isDate) return getIsSameDay(cellValue, value);
            if (isNumeric) return parseNumber(cellValue) === parseNumber(value);
            return stringifyFilterValue(cellValue) === String(value);

        case 'ne':
            if (variant === 'boolean')
                return getBooleanString(cellValue) !== value;
            if (isDate) return !getIsSameDay(cellValue, value);
            if (isNumeric) return parseNumber(cellValue) !== parseNumber(value);
            return stringifyFilterValue(cellValue) !== String(value);

        case 'inArray':
            return Array.isArray(value)
                ? value.includes(stringifyFilterValue(cellValue))
                : true;

        case 'notInArray':
            return Array.isArray(value)
                ? !value.includes(stringifyFilterValue(cellValue))
                : true;

        case 'lt':
        case 'lte':
        case 'gt':
        case 'gte':
            return compare(cellValue, value, operator, isDate);

        case 'isBetween':
            return getIsBetween(cellValue, value, isDate);

        case 'isRelativeToToday':
            return getIsRelativeToToday(cellValue, value);

        case 'isEmpty':
            return getIsEmptyValue(cellValue);

        case 'isNotEmpty':
            return !getIsEmptyValue(cellValue);

        default:
            return true;
    }
}

export const dataTableFilterFn = constructFilterFn({
    filter: (dataValue, filterValue, row, columnId) => {
        const variant = getFilterVariant(
            row.table.getColumn(columnId)?.columnDef.meta as
                | DataTableColumnMeta
                | undefined,
        );
        const item = createPlainFilter(columnId, variant, filterValue);
        return !item || matchesFilter(dataValue, item);
    },
    autoRemove: (value) => value === undefined,
});

export function createDataTableFilteredRowModel<
    TFeatures extends TableFeatures,
    TData extends RowData,
>() {
    return (table: Table<TFeatures, TData>) => {
        const instance = asFilteringTable(table);

        return tableMemo({
            feature: 'dataTableFilteringFeature',
            table,
            fnName: 'table.getFilteredRowModel',
            memoDeps: () => [
                table.getPreFilteredRowModel(),
                instance.atoms.columnFilters?.get(),
                instance.atoms.joinOperator?.get(),
                instance.atoms.globalFilter?.get(),
            ],
            fn: () =>
                getFilteredRowModel(table.getPreFilteredRowModel(), instance),
            onAfterUpdate: skipFirstRun(() => instance.autoResetPageIndex?.()),
        });
    };
}

export function createDataTableFacetedRowModel<
    TFeatures extends TableFeatures,
    TData extends RowData,
>() {
    return (table: Table<TFeatures, TData>, columnId: string) => {
        const instance = asFilteringTable(table);

        return tableMemo({
            feature: 'columnFacetingFeature',
            table,
            fnName: 'createDataTableFacetedRowModel',
            memoDeps: () => [
                table.getPreFilteredRowModel(),
                instance.atoms.columnFilters?.get(),
                instance.atoms.joinOperator?.get(),
                instance.atoms.globalFilter?.get(),
                table.getFilteredRowModel(),
            ],
            fn: () =>
                getFacetedRowModel(
                    table.getPreFilteredRowModel(),
                    columnId,
                    instance,
                ),
        });
    };
}

function getLowercaseText(value: unknown) {
    return stringifyFilterValue(value).toLowerCase();
}

function getBooleanString(value: unknown) {
    return value === true || value === 'true' ? 'true' : 'false';
}

function getIsSameDay(cellValue: unknown, value: unknown) {
    const cell = parseTime(cellValue);
    const target = parseTime(value);
    if (Number.isNaN(cell) || Number.isNaN(target)) return false;
    return cell >= startOfDay(target) && cell <= endOfDay(target);
}

function parseTime(value: unknown) {
    return parseFilterDate(value)?.getTime() ?? Number.NaN;
}

function startOfDay(time: number) {
    const date = new Date(time);
    date.setHours(0, 0, 0, 0);
    return date.getTime();
}

function endOfDay(time: number) {
    const date = new Date(time);
    date.setHours(23, 59, 59, 999);
    return date.getTime();
}

function parseNumber(value: unknown) {
    if (value === '' || value == null) return Number.NaN;
    return typeof value === 'number' ? value : Number(value);
}

function compare(
    cellValue: unknown,
    value: unknown,
    operator: 'lt' | 'lte' | 'gt' | 'gte',
    isDate: boolean,
) {
    if (Array.isArray(value)) return true;

    let cell: number;
    let target: number;

    if (isDate) {
        cell = parseTime(cellValue);
        const time = parseTime(value);
        target =
            operator === 'lt' || operator === 'gte'
                ? startOfDay(time)
                : endOfDay(time);
    } else {
        cell = parseNumber(cellValue);
        target = parseNumber(value);
    }

    if (Number.isNaN(cell) || Number.isNaN(target)) return false;

    switch (operator) {
        case 'lt':
            return cell < target;
        case 'lte':
            return cell <= target;
        case 'gt':
            return cell > target;
        default:
            return cell >= target;
    }
}

function getIsBetween(cellValue: unknown, value: unknown, isDate: boolean) {
    if (!Array.isArray(value) || value.length !== 2) return true;

    const [rawStart, rawEnd] = value;
    const hasStart = stringifyFilterValue(rawStart).trim() !== '';
    const hasEnd = stringifyFilterValue(rawEnd).trim() !== '';

    if (!hasStart && !hasEnd) return true;

    const cell = isDate ? parseTime(cellValue) : parseNumber(cellValue);
    if (Number.isNaN(cell)) return false;

    if (isDate) {
        const start = hasStart ? startOfDay(parseTime(rawStart)) : null;
        const end = hasEnd ? endOfDay(parseTime(rawEnd)) : null;
        return (
            (start === null || cell >= start) && (end === null || cell <= end)
        );
    }

    const start = hasStart ? parseNumber(rawStart) : null;
    const end = hasEnd ? parseNumber(rawEnd) : null;

    return (start === null || cell >= start) && (end === null || cell <= end);
}

function getIsRelativeToToday(cellValue: unknown, value: unknown) {
    if (typeof value !== 'string') return true;

    const [amountRaw, unit] = value.split(' ');
    const amount = Number.parseInt(amountRaw ?? '', 10);
    if (Number.isNaN(amount) || !unit) return true;

    const today = Date.now();
    let start: number;
    let end: number;

    switch (unit) {
        case 'days':
            start = startOfDay(today + amount * DAY_MS);
            end = endOfDay(start);
            break;
        case 'weeks':
            start = startOfDay(today + amount * 7 * DAY_MS);
            end = endOfDay(start + 6 * DAY_MS);
            break;
        case 'months':
            start = startOfDay(today + amount * 30 * DAY_MS);
            end = endOfDay(start + 29 * DAY_MS);
            break;
        default:
            return true;
    }

    const cell = parseTime(cellValue);
    if (Number.isNaN(cell)) return false;
    return cell >= start && cell <= end;
}

function getIsEmptyValue(value: unknown) {
    return (
        value === null ||
        value === undefined ||
        value === '' ||
        (Array.isArray(value) && value.length === 0)
    );
}

interface FilteringColumn<
    TFeatures extends TableFeatures,
    TData extends RowData,
> {
    id: string;
    columnDef: { meta?: unknown };
    getFilterFn?: () => FilterFn<TFeatures, TData> | undefined;
    getCanGlobalFilter?: () => boolean;
}

interface FilteringMembers<
    TFeatures extends TableFeatures,
    TData extends RowData,
> {
    atoms: {
        columnFilters?: { get: () => ColumnFilter[] };
        joinOperator?: { get: () => JoinOperator };
        globalFilter?: { get: () => unknown };
    };
    options: { filterFromLeafRows?: boolean; maxLeafRowFilterDepth?: number };
    getColumn: (
        columnId: string,
    ) => FilteringColumn<TFeatures, TData> | undefined;
    getAllLeafColumns: () => FilteringColumn<TFeatures, TData>[];
    getGlobalFilterFn?: () => FilterFn<TFeatures, TData> | undefined;
    autoResetPageIndex?: () => void;
}

type FilteringInstance<
    TFeatures extends TableFeatures,
    TData extends RowData,
> = FilteringMembers<TFeatures, TData> & Table<TFeatures, TData>;

function asFilteringTable<
    TFeatures extends TableFeatures,
    TData extends RowData,
>(table: Table<TFeatures, TData>) {
    return table as FilteringInstance<TFeatures, TData>;
}

type RowTest<TFeatures extends TableFeatures, TData extends RowData> = (
    row: Row<TFeatures, TData>,
) => boolean;

function getFilteredRowModel<
    TFeatures extends TableFeatures,
    TData extends RowData,
>(
    rowModel: RowModel<TFeatures, TData>,
    instance: FilteringInstance<TFeatures, TData>,
): RowModel<TFeatures, TData> {
    const joinOperator = instance.atoms.joinOperator?.get() ?? 'and';
    const testsByColumn = new Map<string, RowTest<TFeatures, TData>[]>();

    for (const filter of instance.atoms.columnFilters?.get() ?? []) {
        const column = instance.getColumn(filter.id);
        const test = column ? getFilterTest(column, filter) : null;
        if (!test) continue;
        testsByColumn.set(filter.id, [
            ...(testsByColumn.get(filter.id) ?? []),
            test,
        ]);
    }

    const globalTests = getGlobalFilterTests(instance);
    const hasFilters = testsByColumn.size > 0 || globalTests.length > 0;

    for (const row of rowModel.flatRows) {
        const results = makeObjectMap<boolean>();

        if (hasFilters) {
            for (const [columnId, tests] of testsByColumn) {
                results[columnId] =
                    joinOperator === 'or'
                        ? tests.some((test) => test(row))
                        : tests.every((test) => test(row));
            }
            if (globalTests.length > 0) {
                results[GLOBAL_FILTER_ID] = globalTests.some((test) =>
                    test(row),
                );
            }
        }

        setFilterResults(row, results);
    }

    if (!hasFilters || rowModel.rows.length === 0) return rowModel;

    return filterRows(
        rowModel.rows,
        (row) => getRowPasses(row, joinOperator),
        instance,
    );
}

function getFilterTest<TFeatures extends TableFeatures, TData extends RowData>(
    column: FilteringColumn<TFeatures, TData>,
    filter: ColumnFilter,
): RowTest<TFeatures, TData> | null {
    const filterFn = column.getFilterFn?.();

    if (
        !filter.operator &&
        filterFn &&
        !Object.is(filterFn, dataTableFilterFn)
    ) {
        const value =
            filterFn.resolveFilterValue?.(filter.value) ?? filter.value;
        return (row) => filterFn(row, column.id, value);
    }

    const item = normalizeColumnFilter(
        filter,
        getFilterVariant(
            column.columnDef.meta as DataTableColumnMeta | undefined,
        ),
    );
    if (!getIsActiveFilter(item)) return null;

    return (row) => matchesFilter(row.getValue(column.id), item);
}

function getGlobalFilterTests<
    TFeatures extends TableFeatures,
    TData extends RowData,
>(instance: FilteringInstance<TFeatures, TData>): RowTest<TFeatures, TData>[] {
    const globalFilter = instance.atoms.globalFilter?.get();
    const filterFn = instance.getGlobalFilterFn?.();

    if (
        globalFilter === undefined ||
        globalFilter === null ||
        globalFilter === '' ||
        !filterFn
    ) {
        return [];
    }

    const value = filterFn.resolveFilterValue?.(globalFilter) ?? globalFilter;

    return instance
        .getAllLeafColumns()
        .filter((column) => column.getCanGlobalFilter?.())
        .map((column) => (row) => filterFn(row, column.id, value));
}

function setFilterResults<
    TFeatures extends TableFeatures,
    TData extends RowData,
>(row: Row<TFeatures, TData>, results: Record<string, boolean> = {}) {
    filterResultsByRow.set(row, results);
    Object.assign(row, {
        columnFilters: results,
        columnFiltersMeta: makeObjectMap(),
    });
}

function filterRows<TFeatures extends TableFeatures, TData extends RowData>(
    rows: Row<TFeatures, TData>[],
    passes: RowTest<TFeatures, TData>,
    instance: FilteringInstance<TFeatures, TData>,
): RowModel<TFeatures, TData> {
    const maxDepth = instance.options.maxLeafRowFilterDepth ?? 100;
    const flatRows: Row<TFeatures, TData>[] = [];
    const rowsById = makeObjectMap<Row<TFeatures, TData>>();

    function copyRow(row: Row<TFeatures, TData>) {
        const copy = constructRow(
            instance,
            row.id,
            row.original,
            row.index,
            row.depth,
            undefined,
            row.parentId,
        );
        setFilterResults(copy, filterResultsByRow.get(row));
        return copy;
    }

    function addToFlat(subRows: Row<TFeatures, TData>[]) {
        for (const subRow of subRows) {
            flatRows.push(subRow);
            rowsById[subRow.id] = subRow;
            if (subRow.subRows.length) addToFlat(subRow.subRows);
        }
    }

    function fromLeafs(
        rowsToFilter: Row<TFeatures, TData>[],
        depth: number,
    ): Row<TFeatures, TData>[] {
        const filtered: Row<TFeatures, TData>[] = [];

        for (const row of rowsToFilter) {
            const copy = copyRow(row);

            if (row.subRows.length && depth < maxDepth) {
                copy.subRows = fromLeafs(row.subRows, depth + 1);
                if (copy.subRows.length || passes(copy)) filtered.push(copy);
            } else if (passes(copy)) {
                copy.subRows = row.subRows;
                filtered.push(copy);
            }
        }

        return filtered;
    }

    function fromRoot(
        rowsToFilter: Row<TFeatures, TData>[],
        depth: number,
    ): Row<TFeatures, TData>[] {
        const filtered: Row<TFeatures, TData>[] = [];

        for (const row of rowsToFilter) {
            if (!passes(row)) continue;

            if (row.subRows.length && depth < maxDepth) {
                const copy = copyRow(row);
                filtered.push(copy);
                flatRows.push(copy);
                rowsById[copy.id] = copy;
                copy.subRows = fromRoot(row.subRows, depth + 1);
            } else {
                filtered.push(row);
                flatRows.push(row);
                rowsById[row.id] = row;
                if (row.subRows.length) addToFlat(row.subRows);
            }
        }

        return filtered;
    }

    if (instance.options.filterFromLeafRows) {
        const filtered = fromLeafs(rows, 0);
        addToFlat(filtered);
        return { rows: filtered, flatRows, rowsById };
    }

    return { rows: fromRoot(rows, 0), flatRows, rowsById };
}

function getRowPasses<TFeatures extends TableFeatures, TData extends RowData>(
    row: Row<TFeatures, TData>,
    joinOperator: JoinOperator,
    excludedColumnId?: string,
) {
    const results = filterResultsByRow.get(row) ?? {};

    if (
        excludedColumnId !== GLOBAL_FILTER_ID &&
        results[GLOBAL_FILTER_ID] === false
    ) {
        return false;
    }

    const columnIds = Object.keys(results).filter(
        (id) => id !== GLOBAL_FILTER_ID && id !== excludedColumnId,
    );
    if (columnIds.length === 0) return true;

    return joinOperator === 'or'
        ? columnIds.some((id) => results[id])
        : columnIds.every((id) => results[id]);
}

function getFacetedRowModel<
    TFeatures extends TableFeatures,
    TData extends RowData,
>(
    rowModel: RowModel<TFeatures, TData>,
    columnId: string,
    instance: FilteringInstance<TFeatures, TData>,
): RowModel<TFeatures, TData> {
    const globalFilter = instance.atoms.globalFilter?.get();
    const hasGlobalFilter =
        columnId !== GLOBAL_FILTER_ID &&
        globalFilter !== undefined &&
        globalFilter !== null &&
        globalFilter !== '';
    const hasOtherFilters =
        hasGlobalFilter ||
        (instance.atoms.columnFilters?.get() ?? []).some(
            (filter) => filter.id !== columnId,
        );

    if (!hasOtherFilters || rowModel.rows.length === 0) return rowModel;

    const joinOperator = instance.atoms.joinOperator?.get() ?? 'and';

    return filterRows(
        rowModel.rows,
        (row) => getRowPasses(row, joinOperator, columnId),
        instance,
    );
}

