function FacetedCommandItem({
    className,
    onPointerDownCapture,
    onMouseDown,
    ...props
}: React.ComponentProps<typeof CommandPrimitive.Item>) {
    return (
        <CommandPrimitive.Item
            className={cn(
                "group/command-item relative flex cursor-default items-center gap-1.5 rounded-md px-1.5 py-1 text-sm outline-hidden select-none data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50 data-[selected=true]:bg-accent data-[selected=true]:text-accent-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 data-[selected=true]:*:[svg]:text-accent-foreground",
                className,
            )}
            onPointerDownCapture={composeEventHandlers(
                onPointerDownCapture,
                (event) => {
                    // A focusable item steals the input on pointerdown.
                    event.preventDefault();
                    if (event.pointerType === 'touch') return;
                    event.currentTarget
                        .closest('[cmdk-root]')
                        ?.querySelector<HTMLInputElement>('[cmdk-input]')
                        ?.focus();
                },
            )}
            onMouseDown={composeEventHandlers(onMouseDown, (event) => {
                // iOS Safari can emit a synthetic mousedown without a pointerdown.
                event.preventDefault();
            })}
            {...props}
        />
    );
}

interface FacetedItemProps extends React.ComponentProps<
    typeof CommandPrimitive.Item
> {
    value: string;
}

function FacetedItem({ value, onSelect, ...props }: FacetedItemProps) {
    const store = useFacetedStore('FacetedItem');
    const isSelected = useFacetedStoreSelector(store, (state) =>
        getIsValueSelected(state.value, state.multiple, value),
    );

    return (
        <FacetedCommandItem
            data-slot="faceted-item"
            data-checked={isSelected || undefined}
            aria-checked={isSelected}
            onSelect={() => {
                if (onSelect) {
                    onSelect(value);
                    return;
                }
                store.selectItem(value);
            }}
            {...props}
        />
    );
}

