                    data-slot="faceted-clear"
                    className={cn('justify-center text-center', className)}
                    onSelect={(value) => {
                        onSelect?.(value);
                        store.clear();
                    }}
                    {...props}
                >
                    {children}
                </FacetedCommandItem>
            </FacetedGroup>
        </>
    );
}

function FacetedSeparator({
