interface DataTableColumnHeaderProps<
    TData extends RowData,
    TValue,
> extends React.ComponentProps<typeof DropdownMenuTrigger> {
    column: Column<DataTableFeatures, TData, TValue>;
    label: string;
}

export function DataTableColumnHeader<TData extends RowData, TValue>({
    column,
    label,
    className,
    ...props
}: DataTableColumnHeaderProps<TData, TValue>) {
    if (!column.getCanSort() && !column.getCanHide()) {
        return <div className={className}>{label}</div>;
    }

    return (
        <Subscribe
            source={column.table.store}
            selector={(state) => ({
                isVisible: state.columnVisibility[column.id] !== false,
                sortDirection: getSortDirection(state.sorting, column.id),
            })}
        >
            {(headerState) => (
                <DataTableColumnHeaderMenu
                    column={column}
                    label={label}
                    className={className}
                    isVisible={headerState.isVisible}
                    sortDirection={headerState.sortDirection}
                    {...props}
                />
            )}
        </Subscribe>
    );
}

interface DataTableColumnHeaderMenuProps<
    TData extends RowData,
    TValue,
> extends DataTableColumnHeaderProps<TData, TValue> {
    isVisible: boolean;
    sortDirection: SortDirection | 'none';
}

function DataTableColumnHeaderMenu<TData extends RowData, TValue>({
    column,
    label,
    className,
    isVisible,
    sortDirection,
    ...props
}: DataTableColumnHeaderMenuProps<TData, TValue>) {
    function onSortDirectionChange(direction: SortDirection) {
        if (sortDirection === direction) {
            column.clearSorting();
            return;
        }

        column.toggleSorting(direction === 'desc', true);
    }

    return (
        <DropdownMenu>
            <DropdownMenuTrigger
                className={cn(
                    '-ms-1.5 flex h-8 items-center gap-1.5 rounded-md px-2 py-1.5 hover:bg-accent focus:ring-1 focus:ring-ring focus:outline-none data-[state=open]:bg-accent rtl:flex-row-reverse [&_svg]:size-4 [&_svg]:shrink-0 [&_svg]:text-muted-foreground',
                    className,
                )}
                {...props}
            >
                {label}
                {column.getCanSort() &&
                    (sortDirection === 'desc' ? (
                        <ChevronDown />
                    ) : sortDirection === 'asc' ? (
                        <ChevronUp />
                    ) : (
                        <ChevronsUpDown />
                    ))}
            </DropdownMenuTrigger>
            <DropdownMenuContent
                align="start"
                className="w-28 data-[state=closed]:fill-mode-forwards"
            >
                {column.getCanSort() && (
                    <>
                        <DropdownMenuCheckboxItem
                            className="[&_svg]:text-muted-foreground"
                            checked={sortDirection === 'asc'}
                            onClick={() => onSortDirectionChange('asc')}
                        >
                            <ChevronUp />
                            Asc
                        </DropdownMenuCheckboxItem>
                        <DropdownMenuCheckboxItem
                            className="[&_svg]:text-muted-foreground"
                            checked={sortDirection === 'desc'}
                            onClick={() => onSortDirectionChange('desc')}
                        >
                            <ChevronDown />
                            Desc
                        </DropdownMenuCheckboxItem>
                    </>
                )}
                {column.getCanHide() && (
                    <DropdownMenuCheckboxItem
                        className="[&_svg]:text-muted-foreground"
                        checked={!isVisible}
                        onClick={() => column.toggleVisibility(false)}
                    >
                        <EyeOff />
                        Hide
                    </DropdownMenuCheckboxItem>
                )}
            </DropdownMenuContent>
        </DropdownMenu>
    );
}

function getSortDirection(
    sorting: SortingState,
    columnId: string,
): SortDirection | 'none' {
    const sort = sorting.find((sort) => sort.id === columnId);
    if (!sort) return 'none';
    return sort.desc ? 'desc' : 'asc';
}

import type {
    CellContext,
    HeaderContext,
    RowData,
} from '@tanstack/react-table';

import { DataTableColumnHeader } from '@/components/data-table/data-table-column-header';
import type { DataTableFeatures } from '@/lib/data-table-features';
import { formatDate } from '@/lib/data-table-format';
import type { DataTableColumnMeta } from '@/lib/data-table-types';

/**
 * Cabecera de una columna que no personaliza el componente: la etiqueta que
 * declara la clase de la tabla, con orden y ocultar si la columna lo permite.
 */
export function DataTableDefaultHeader<TData extends RowData, TValue>({
    column,
}: HeaderContext<DataTableFeatures, TData, TValue>) {
    const meta = column.columnDef.meta as DataTableColumnMeta | undefined;

    return (
        <DataTableColumnHeader
            column={column}
            label={meta?.label ?? column.id}
        />
    );
}

/**
 * Celda de una columna que no personaliza el componente, formateada según el
 * filtro que declara la clase de la tabla.
 */
export function DataTableDefaultCell<TData extends RowData, TValue>({
    cell,
    column,
}: CellContext<DataTableFeatures, TData, TValue>) {
    return formatCellValue(
        column.columnDef.meta as DataTableColumnMeta | undefined,
        cell.getValue(),
    );
}

export function formatCellValue(
    meta: DataTableColumnMeta | undefined,
    value: unknown,
): string {
    if (value === null || value === undefined || value === '') {
        return '';
    }

    if (Array.isArray(value)) {
        return value.map((item) => formatCellValue(meta, item)).join(', ');
    }

    switch (meta?.variant) {
        case 'date':
            return typeof value === 'string' || typeof value === 'number'
                ? formatDate(value)
                : String(value);
        case 'boolean':
            // Algunas bases (SQLite, MySQL) devuelven 1/0 en lugar de true/false.
            return value === true || value === 1 || value === '1'
                ? 'Yes'
                : 'No';
        case 'select':
        case 'multi-select':
            return getOptionLabel(meta, toPrimitive(value));
        case 'number':
            return meta.unit ? `${String(value)} ${meta.unit}` : String(value);
    }

    if (typeof value === 'boolean') {
        return value ? 'Yes' : 'No';
    }

    return typeof value === 'object' ? JSON.stringify(value) : String(value);
}

/**
 * Etiqueta de una opción (select / multi-select) tal como la declara el
 * servidor, para mostrar `Administrador` en lugar de `admin` en una celda.
 */
export function getOptionLabel(
    meta: DataTableColumnMeta | undefined,
    value: string | number | boolean | null | undefined,
): string {
    const text = value === null || value === undefined ? '' : String(value);
    const options = meta && 'options' in meta ? meta.options : undefined;

    return options?.find((option) => option.value === text)?.label ?? text;
}

function toPrimitive(value: unknown): string | number | boolean | null {
    return typeof value === 'string' ||
        typeof value === 'number' ||
        typeof value === 'boolean'
        ? value
        : null;
}

