                <DataTableDateFilterContent
                    column={column}
                    columnFilterValue={filterValue}
                    {...props}
                />
            )}
        </Subscribe>
    );
}

function DataTableDateFilterContent<TData extends RowData>({
    column,
    title = column.columnDef.meta?.label ?? column.id,
    multiple,
    columnFilterValue,
}: DataTableDateFilterProps<TData> & {
    columnFilterValue: unknown;
}) {
    const dir = useDirection();
    const selectedDates = React.useMemo<DateSelection>(() => {
        if (!columnFilterValue) {
            return multiple ? { from: undefined, to: undefined } : [];
        }

        const timestamps = parseColumnFilterValue(columnFilterValue);
        if (multiple) {
            return {
                from: parseAsDate(timestamps[0]),
                to: parseAsDate(timestamps[1]),
            };
        }

        const date = parseAsDate(timestamps[0]);
        return date ? [date] : [];
    }, [columnFilterValue, multiple]);

    const onSelect = React.useCallback(
        (date: Date | DateRange | undefined) => {
            if (!date) {
                column.setFilterValue(undefined);
                return;
            }

            if (multiple && !('getTime' in date)) {
                const from = date.from?.getTime();
                const to = date.to?.getTime();
                column.setFilterValue(from || to ? [from, to] : undefined);
            } else if (!multiple && 'getTime' in date) {
                column.setFilterValue(date.getTime());
            }
        },
        [column, multiple],
    );

    const onReset = React.useCallback(
        (event: React.MouseEvent) => {
            event.stopPropagation();
            column.setFilterValue(undefined);
        },
        [column],
    );

    const hasValue = getIsDateRange(selectedDates)
        ? Boolean(selectedDates.from || selectedDates.to)
        : selectedDates.length > 0;
    const dateText = getIsDateRange(selectedDates)
        ? formatDateRange(selectedDates)
        : formatDate(selectedDates[0]);

    const label = (
        <span className="flex items-center gap-2">
            <span>{title}</span>
            {hasValue && (
                <>
                    <Separator
                        orientation="vertical"
                        className="mx-0.5 data-[orientation=vertical]:h-4 data-[orientation=vertical]:self-center"
                    />
                    <span>{dateText}</span>
                </>
            )}
        </span>
    );

    return (
        <Popover>
            <PopoverTrigger asChild>
                <Button variant="outline">
                    {hasValue ? (
                        <span
                            aria-hidden="true"
                            className="rounded-sm opacity-70 transition-opacity hover:opacity-100"
                            onClick={onReset}
                        >
                            <CircleX />
                        </span>
                    ) : (
                        <CalendarIcon />
                    )}
                    {label}
                </Button>
            </PopoverTrigger>
            <PopoverContent
                aria-label={`${title} filter`}
                dir={dir}
                className="w-auto p-0"
                align="start"
            >
                {multiple ? (
                    <Calendar
                        autoFocus
                        captionLayout="dropdown"
                        mode="range"
                        selected={
                            getIsDateRange(selectedDates)
                                ? selectedDates
                                : { from: undefined, to: undefined }
                        }
                        onSelect={onSelect}
                    />
                ) : (
                    <Calendar
                        captionLayout="dropdown"
                        mode="single"
                        selected={
                            !getIsDateRange(selectedDates)
                                ? selectedDates[0]
                                : undefined
                        }
                        onSelect={onSelect}
                    />
                )}
                {hasValue && (
                    <div className="border-t p-3">
                        <Button
                            aria-label={`Clear ${title} filter`}
                            variant="outline"
                            className="w-full"
                            onClick={onReset}
                        >
                            Clear
                        </Button>
                    </div>
                )}
            </PopoverContent>
        </Popover>
    );
}

function parseColumnFilterValue(value: unknown) {
    if (Array.isArray(value)) {
        return value.map((item) =>
            typeof item === 'number' || typeof item === 'string'
                ? item
                : undefined,
        );
    }
    if (typeof value === 'string' || typeof value === 'number') return [value];
    return [];
}

function parseAsDate(timestamp: number | string | undefined): Date | undefined {
    if (!timestamp) return undefined;
    const numericTimestamp =
        typeof timestamp === 'string' ? Number(timestamp) : timestamp;
    const date = new Date(numericTimestamp);
    return !Number.isNaN(date.getTime()) ? date : undefined;
}

function getIsDateRange(value: DateSelection): value is DateRange {
    return !Array.isArray(value);
}

function formatDateRange(range: DateRange) {
    if (range.from && range.to) {
        return `${formatDate(range.from)} - ${formatDate(range.to)}`;
    }
    return formatDate(range.from ?? range.to);
}

