    pageSize: number;
    selectedRowCount: number;
    visibleSelectedRowCount: number;
    pageSizeOptions: number[];
}

function DataTablePaginationContent<TData extends RowData>({
    table,
    pageIndex,
    pageSize,
    selectedRowCount,
    visibleSelectedRowCount,
    pageSizeOptions,
    className,
    ...props
}: DataTablePaginationContentProps<TData>) {
    const pageSizeLabelId = React.useId();
    const pageCount = table.getPageCount();
    const canPreviousPage = table.getCanPreviousPage();
    const canNextPage = table.getCanNextPage();

    return (
        <div
            data-slot="data-table-pagination"
            className={cn(
                'flex w-full flex-col-reverse items-center justify-between gap-4 overflow-auto p-1 sm:flex-row sm:gap-8',
                className,
            )}
            {...props}
        >
            <div
                role="status"
                className="flex-1 text-sm whitespace-nowrap text-muted-foreground"
            >
                {selectedRowCount > 0 && (
                    <>
                        {selectedRowCount}{' '}
                        {selectedRowCount === 1 ? 'row' : 'rows'} selected
                        {selectedRowCount > visibleSelectedRowCount
                            ? ` (${selectedRowCount - visibleSelectedRowCount} not shown)`
                            : ''}
                        .
                    </>
                )}
            </div>
            <div className="flex flex-col-reverse items-center gap-4 sm:flex-row sm:gap-6 lg:gap-8">
                <div className="flex items-center gap-2">
                    <p
                        id={pageSizeLabelId}
                        className="text-sm font-medium whitespace-nowrap"
                    >
                        Rows per page
                    </p>
                    <Select
                        value={`${pageSize}`}
                        onValueChange={(value) => {
                            table.setPageSize(Number(value));
                        }}
                    >
                        <SelectTrigger
                            aria-labelledby={pageSizeLabelId}
                            className="w-18"
                        >
                            <SelectValue placeholder={pageSize} />
                        </SelectTrigger>
                        <SelectContent side="top">
                            <SelectGroup>
                                {pageSizeOptions.map((pageSize) => (
                                    <SelectItem
                                        key={pageSize}
                                        value={`${pageSize}`}
                                    >
                                        {pageSize}
                                    </SelectItem>
                                ))}
                            </SelectGroup>
                        </SelectContent>
                    </Select>
                </div>
                <div
                    role="status"
                    className="flex items-center justify-center text-sm font-medium"
                >
                    Page {pageIndex + 1} of {pageCount}
                </div>
                <div className="flex items-center gap-2">
                    <Button
                        aria-label="Go to first page"
                        variant="outline"
                        size="icon"
                        className="hidden lg:flex"
                        onClick={() => table.setPageIndex(0)}
                        disabled={!canPreviousPage}
                    >
                        <ChevronsLeft className="rtl:rotate-180" />
                    </Button>
                    <Button
                        aria-label="Go to previous page"
                        variant="outline"
                        size="icon"
                        onClick={() => table.previousPage()}
                        disabled={!canPreviousPage}
                    >
                        <ChevronLeft className="rtl:rotate-180" />
                    </Button>
                    <Button
                        aria-label="Go to next page"
                        variant="outline"
                        size="icon"
                        onClick={() => table.nextPage()}
                        disabled={!canNextPage}
                    >
                        <ChevronRight className="rtl:rotate-180" />
                    </Button>
                    <Button
                        aria-label="Go to last page"
                        variant="outline"
                        size="icon"
                        className="hidden lg:flex"
                        onClick={() => table.setPageIndex(pageCount - 1)}
                        disabled={!canNextPage}
                    >
                        <ChevronsRight className="rtl:rotate-180" />
                    </Button>
                </div>
            </div>
        </div>
    );
}

