interface DataTableToolbarProps<
    TData extends RowData,
> extends React.ComponentProps<'div'> {
    table: ReactTable<DataTableFeatures, TData, unknown>;
    /** Muestra la búsqueda global; por defecto, si el servidor la permite. */
    searchable?: boolean;
    searchPlaceholder?: string;
}

/**
 * Disposición por defecto: búsqueda, filtros y Reset a la izquierda; `children`
 * y el menú de columnas a la derecha. Para otro orden, compón las piezas
 * (`DataTableSearch`, `DataTableFilters`, `DataTableFilter`,
 * `DataTableResetButton`, `DataTableViewOptions`) en tu propio contenedor.
 */
export function DataTableToolbar<TData extends RowData>({
    table,
    searchable,
    searchPlaceholder,
    children,
    className,
    ...props
}: DataTableToolbarProps<TData>) {
    return (
        <div
            data-slot="data-table-toolbar"
            className={cn(
                'flex w-full items-start justify-between gap-2 p-1',
                className,
            )}
            {...props}
        >
            <div className="flex flex-1 flex-wrap items-center gap-2">
                <DataTableSearch
                    table={table}
                    searchable={searchable}
                    placeholder={searchPlaceholder}
                />
                <DataTableFilters table={table} />
                <DataTableResetButton table={table} />
            </div>
            <div className="flex items-center gap-2">
                {children}
                <DataTableViewOptions table={table} align="end" />
            </div>
        </div>
    );
}

interface DataTableSearchProps<
    TData extends RowData,
> extends React.ComponentProps<'input'> {
    table: ReactTable<DataTableFeatures, TData, unknown>;
    /** Muestra la búsqueda global; por defecto, si el servidor la permite. */
    searchable?: boolean;
}

/**
 * Búsqueda global (`?search=`). No se muestra si la clase de la tabla no
 * declara columnas `searchable()`, salvo que se fuerce con `searchable`.
 */
export function DataTableSearch<TData extends RowData>({
    table,
    searchable,
    placeholder = 'Search...',
    className,
    ...props
}: DataTableSearchProps<TData>) {
    if (!(searchable ?? table.options.meta?.searchable)) {
        return null;
    }

    return (
        <Subscribe source={table.atoms.globalFilter}>
            {(globalFilter) => (
                <Input
                    type="search"
                    aria-label={placeholder}
                    placeholder={placeholder}
                    className={cn('w-40 lg:w-64', className)}
                    {...props}
                    value={typeof globalFilter === 'string' ? globalFilter : ''}
                    onChange={(event) =>
                        table.setGlobalFilter(event.target.value)
                    }
                />
            )}
        </Subscribe>
    );
}

interface DataTableFiltersProps<TData extends RowData> {
    table: ReactTable<DataTableFeatures, TData, unknown>;
    /** Ids de las columnas a mostrar, en este orden; por defecto, todas. */
    columns?: string[];
}

/**
 * Un control por cada columna filtrable, en el orden de la tabla o en el de
 * `columns`. Sin envoltorio: se colocan dentro del contenedor del padre.
 */
export function DataTableFilters<TData extends RowData>({
    table,
    columns,
}: DataTableFiltersProps<TData>) {
    const filterable = table
        .getAllColumns()
        .filter((column) => column.getCanFilter());
    const shown = columns
        ? columns.flatMap((id) =>
              filterable.filter((column) => column.id === id),
          )
        : filterable;

    return (
        <>
            {shown.map((column) => (
                <DataTableToolbarFilter key={column.id} column={column} />
            ))}
        </>
    );
}

interface DataTableFilterProps<TData extends RowData> {
    table: ReactTable<DataTableFeatures, TData, unknown>;
    /** Id de la columna en la clase de la tabla. */
    column: string;
}

/**
 * El filtro de una sola columna, para colocarlo aparte del resto.
 */
export function DataTableFilter<TData extends RowData>({
    table,
    column,
}: DataTableFilterProps<TData>) {
    const found = table
        .getAllColumns()
        .find((item) => item.id === column && item.getCanFilter());

    return found ? <DataTableToolbarFilter column={found} /> : null;
}

interface DataTableResetButtonProps<
    TData extends RowData,
> extends React.ComponentProps<typeof Button> {
    table: ReactTable<DataTableFeatures, TData, unknown>;
}

/**
 * Limpia los filtros y la búsqueda; solo aparece cuando hay alguno activo.
 */
export function DataTableResetButton<TData extends RowData>({
    table,
    children = 'Reset',
    ...props
}: DataTableResetButtonProps<TData>) {
    function onReset() {
        table.resetColumnFilters(true);
        table.resetGlobalFilter(true);
        table.resetJoinOperator(true);
    }

    return (
        <Subscribe
            source={table.store}
            selector={(state) =>
                state.columnFilters.length > 0 || Boolean(state.globalFilter)
            }
        >
            {(isFiltered) =>
                isFiltered && (
                    <Button
                        aria-label="Reset filters"
                        variant="outline"
                        onClick={onReset}
                        {...props}
                    >
                        <X />
                        {children}
                    </Button>
                )
            }
        </Subscribe>
    );
}

const BOOLEAN_OPTIONS = [
    { label: 'Yes', value: 'true' },
    { label: 'No', value: 'false' },
];

interface DataTableToolbarFilterProps<TData extends RowData> {
    column: Column<DataTableFeatures, TData>;
}

function DataTableToolbarFilter<TData extends RowData>({
    column,
}: DataTableToolbarFilterProps<TData>) {
    const columnMeta = column.columnDef.meta;
    if (!columnMeta?.variant) return null;

    const title = columnMeta.label ?? column.id;
    const placeholder = columnMeta.placeholder ?? columnMeta.label;
    const filterVariant = getFilterVariant(columnMeta);

    switch (filterVariant) {
        case 'text':
            return (
                <DataTableFilterInput
                    column={column}
                    placeholder={placeholder}
                    className="w-40 lg:w-56"
                />
            );

        case 'number':
            return (
                <DataTableFilterInput
                    column={column}
                    type="number"
                    inputMode="numeric"
                    placeholder={placeholder}
                    unit={
                        columnMeta.variant === 'number'
                            ? columnMeta.unit
                            : undefined
                    }
                    className="w-30"
                />
            );

        case 'range':
            return <DataTableSliderFilter column={column} title={title} />;

        case 'date':
        case 'date-range':
            return (
                <DataTableDateFilter
                    column={column}
                    title={title}
                    multiple={filterVariant === 'date-range'}
                />
            );

        case 'boolean':
            return (
                <DataTableFacetedFilter
                    column={column}
                    title={title}
                    options={BOOLEAN_OPTIONS}
                />
            );

        case 'select':
        case 'multi-select':
            return (
                <DataTableFacetedFilter
                    column={column}
                    title={title}
                    options={getColumnSelectOptions(columnMeta)}
                    multiple={filterVariant === 'multi-select'}
                />
            );

        default:
            return null;
    }
}

interface DataTableFilterInputProps<
    TData extends RowData,
> extends React.ComponentProps<'input'> {
    column: Column<DataTableFeatures, TData>;
    unit?: string;
}

function DataTableFilterInput<TData extends RowData>({
    column,
    type = 'text',
    unit,
    className,
    ...props
}: DataTableFilterInputProps<TData>) {
    return (
        <Subscribe
            source={column.table.atoms.columnFilters}
            selector={() => column.getFilterValue()}
        >
            {(filterValue) => {
                const inputProps = {
                    type,
                    ...props,
                    value: readFilterInputValue(filterValue),
                    onChange: (event: React.ChangeEvent<HTMLInputElement>) =>
                        column.setFilterValue(event.target.value || undefined),
                };

                if (!unit)
                    return <Input {...inputProps} className={className} />;

                return (
                    <InputGroup className={className}>
                        <InputGroupInput {...inputProps} />
                        <InputGroupAddon align="inline-end">
                            <InputGroupText>{unit}</InputGroupText>
                        </InputGroupAddon>
                    </InputGroup>
                );
            }}
        </Subscribe>
    );
}

function readFilterInputValue(value: unknown) {
    if (typeof value === 'string' || typeof value === 'number') {
        return String(value);
    }

    if (Array.isArray(value)) {
        return value.join(',');
    }

    return '';
}

